#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){string s;cin>>s;int n=s.size();
vector<int>idx(n);
for(int i=0;i<n;++i)scanf("%d",&idx[i]);
string r(n,' ');
for(int i=0;i<n;++i)r[idx[i]]=s[i];
printf("%s\n",r.c_str());return 0;}

